+       importOn,
+       importName,
+       forwardRefName,
+     );
+     if (traitImportChanges.length === 0) continue;
+ 
+     let description = `Import ${importName}`;
+     if (potentialImport.moduleSpecifier !== undefined) {
+       description += ` from '${potentialImport.moduleSpecifier}' on ${importOn.name!.text}`;
+     }
